    body += `<rect x="${horizontal}" y="${vertical}" width="56" height="66" style="fill:${fill(tone)};stroke:${color(tone)};stroke-width:2"></rect>` + text(horizontal + 28, vertical + 41, label, { width: 48, anchor: 'middle', weight: 700 });
